#include "web/web_assets.h"

#include <Arduino.h>

#include "project/project_assets.h"

// The project's mark and icons, generated by tools/gen_web_assets.py from
// project/assets/logo.svg into project/project_assets.cpp. Served from ROM
// and cached by the browser for a week: they never change without a new
// firmware, and the stylesheet URL carries the version anyway.

#define ASSET_CACHE "public, max-age=604800"

static void sendAsset(WebServer &srv, const char *type, const uint8_t *data, size_t len) {
  srv.sendHeader("Cache-Control", ASSET_CACHE);
  srv.send_P(200, type, (PGM_P)data, len);
}

void registerAssetRoutes(WebServer &srv) {
  srv.on("/logo.svg", HTTP_GET, [&srv]() {
    sendAsset(srv, "image/svg+xml", (const uint8_t *)PROJECT_LOGO_SVG, strlen_P(PROJECT_LOGO_SVG));
  });
  // Browsers ask for /favicon.ico on their own. The content is a PNG; no
  // browser in the last decade insists on the ICO container at that path.
  srv.on("/favicon.ico", HTTP_GET, [&srv]() {
    sendAsset(srv, "image/png", PROJECT_FAVICON_PNG, PROJECT_FAVICON_PNG_LEN);
  });
  srv.on("/favicon.png", HTTP_GET, [&srv]() {
    sendAsset(srv, "image/png", PROJECT_FAVICON_PNG, PROJECT_FAVICON_PNG_LEN);
  });
  srv.on("/apple-touch-icon.png", HTTP_GET, [&srv]() {
    sendAsset(srv, "image/png", PROJECT_TOUCH_ICON_PNG, PROJECT_TOUCH_ICON_PNG_LEN);
  });
}
